    // 判断是否是有效的二叉搜索树的前序遍历
    static boolean isValid(Node root, int start, int end, List<Integer> preOrder) {
        if (start == end) {
            return true;
        }

        int i = start + 1;
        // 找到右子树的起点
        while (i <= end && preOrder.get(i) < root.value) {
            i++;
        }

        int j = i;
        // 验证右子树的所有值是否大于根节点
        while (j <= end && preOrder.get(j) > root.value) {
            j++;
        }

        // 若 j 未能完全遍历完，则说明不符合BST规则
        if (j <= end) {
            return false;
        }
​
        // 递归构建左子树
        if (i > start + 1) {
            root.left = new Node(preOrder.get(start + 1));
            if (!isValid(root.left, start + 1, i - 1, preOrder)) {
                return false;
            }
        }

        // 递归构建右子树
        if (i <= end) {
            root.right = new Node(preOrder.get(i));
            return isValid(root.right, i, end, preOrder);
        }
​
        return true;
    }
​
    // 获取左伞坠
    static int leftBottom(Node root, int level) {
        if (root.left != null) {
            return leftBottom(root.left, level + 1);
        }
        if (level == 0) {
            return 0;
        }
        if (root.right != null) {
            return leftBottom(root.right, level + 1);
        }
        return root.value;
    }
​
    // 获取右伞坠
    static int rightBottom(Node root, int level) {
        if (root.right != null) {
            return rightBottom(root.right, level + 1);
        }
        if (level == 0) {
            return 0;
        }
        if (root.left != null) {
            return rightBottom(root.left, level + 1);
        }
        return root.value;
    }
​
    // 中序遍历
    static void dfs(Node root, List<Integer> res) {
        if (root == null) {
            return;
        }
        dfs(root.left, res);
        res.add(root.value);
        dfs(root.right, res);
    }
