import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 定义树节点
type Node struct {
    value int
    left  *Node
    right *Node
}
​
// 判断是否是有效的BST前序遍历
func isValid(root *Node, start, end int, preOrder []int) bool {
    if start == end {
        return true
    }
​
    i := start + 1
    // 找到右子树的起点
    for i <= end && preOrder[i] < root.value {
        i++
    }
​
    j := i
    // 验证右子树的所有值是否大于根节点
    for j <= end && preOrder[j] > root.value {
        j++
    }
​
    // 若 j 未能完全遍历完，则说明不符合BST规则
    if j <= end {
        return false
    }
​
    // 递归构建左子树
    if i > start+1 {
        root.left = &Node{value: preOrder[start+1]}
        if !isValid(root.left, start+1, i-1, preOrder) {
            return false
        }
    }
​
    // 递归构建右子树
    if i <= end {
        root.right = &Node{value: preOrder[i]}
        return isValid(root.right, i, end, preOrder)
    }
​
    return true
}
​
// 获取左伞坠
func leftBottom(root *Node, level int) int {
    if root.left != nil {
        return leftBottom(root.left, level+1)
    }
    if level == 0 {
        return 0
    }
    if root.right != nil {
        return leftBottom(root.right, level+1)
    }
    return root.value
}
​
// 获取右伞坠
func rightBottom(root *Node, level int) int {
    if root.right != nil {
        return rightBottom(root.right, level+1)
    }
    if level == 0 {
        return 0
    }
    if root.left != nil {
        return rightBottom(root.left, level+1)
    }
    return root.value
}
​
func main() {
    // 读取输入
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    line = strings.TrimSpace(line)

    // 解析输入为整数数组
    strNums := strings.Split(line, " ")
    preOrder := make([]int, len(strNums))
    for i, str := range strNums {
        preOrder[i], _ = strconv.Atoi(str)
    }
​
    root := &Node{value: preOrder[0]}
​
    // 验证是否为合法 BST
    if !isValid(root, 0, len(preOrder)-1, preOrder) {
        fmt.Println("0 0 0")
    } else {
        fmt.Printf("1 %d %d\n", leftBottom(root, 0), rightBottom(root, 0))
    }
}
